	quality_conclusion TEXT NOT NULL DEFAULT '',
	received_at        TEXT,
	refundable_amount  INTEGER NOT NULL DEFAULT 0,
	reject_reason      TEXT NOT NULL DEFAULT '',
	created_at         TEXT NOT NULL,
	updated_at         TEXT NOT NULL
);

