}

func scanRefunds(rows *sql.Rows) ([]Refund, error) {
	refunds := []Refund{}
	for rows.Next() {
		refund, err := scanRefund(rows)
		if err != nil {
			return nil, err
		}
		refunds = append(refunds, *refund)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return refunds, nil
}
