	total := int64(0)
	for _, refund := range refunds {
		total += refund.Amount
	}
	if total != 100 {
		t.Fatalf("total refunded = %d, want 100", total)
	}
	record, _ := st.GetReturn(context.Background(), id)
	if record.Status != StatusRefunded {
		t.Fatalf("status = %s, want refunded", record.Status)
	}
}

