	go func() { defer wg.Done(); _, errs[0] = st.ApproveReturn(context.Background(), created.ID, "ok", "2026-09-30T10:00:00Z", 5) }()
	go func() { defer wg.Done(); _, errs[1] = st.RejectReturn(context.Background(), created.ID, "no") }()
	wg.Wait()

